"""Acceptance tests for WP-32 (sound effects generated by ElevenLabs). Written by the maintainer; do not edit."""

from __future__ import annotations

import json
import shutil
from pathlib import Path
from typing import Any

import pytest
import yaml
from test_voice import EP, FAKE_KEY, FIX, FakeTransport

from karagoz import cli
from karagoz.voice.elevenlabs import SFX_MODEL, ElevenLabs, sound_cache_key, synthesize_sounds


class FakeBytes:
    def __init__(self, status: int = 200) -> None:
        self.calls: list[tuple[str, dict[str, Any], dict[str, str]]] = []
        self.status = status

    def __call__(self, url: str, body: dict[str, Any], headers: dict[str, str]) -> tuple[int, bytes]:
        self.calls.append((url, body, headers))
        if self.status != 200:
            return self.status, json.dumps({"detail": {"message": f"bad key {FAKE_KEY}"}}).encode()
        return 200, b"SFX:" + body["text"].encode()


def client(b: FakeBytes) -> ElevenLabs:
    return ElevenLabs(transport=FakeTransport(), bytes_transport=b, api_key=lambda: FAKE_KEY)


SOUNDS = [
    {"id": "S01", "description": "cup set down on a glass table", "at": "L01.end"},
    {"id": "S02", "description": "soft sitcom music bed", "at": "sh01.in", "kind": "music"},
    {"id": "S03", "description": "door slam", "at": "L02.end"},
]


@pytest.fixture
def prod(tmp_path: Path) -> Path:
    p = tmp_path / "prod"
    (p / EP).mkdir(parents=True)
    lines = yaml.safe_load((FIX / "lines.yaml").read_text(encoding="utf-8"))
    lines["sounds"] = SOUNDS
    (p / EP / "lines.yaml").write_text(yaml.safe_dump(lines, allow_unicode=True), encoding="utf-8")
    (p / "voices.yaml").write_text(
        'version: 1\nvoices:\n  ali: { voice_id: "v-ali" }\n  ayse: { voice_id: "v-ayse" }\n'
    )
    return p


def test_sound_request() -> None:
    b = FakeBytes()
    audio = client(b).sound("door slam")
    assert audio == b"SFX:door slam"
    url, body, headers = b.calls[0]
    assert url == "https://api.elevenlabs.io/v1/sound-generation?output_format=mp3_44100_128"
    assert body == {"text": "door slam", "model_id": SFX_MODEL}
    assert SFX_MODEL == "eleven_text_to_sound_v2"
    assert headers["xi-api-key"] == FAKE_KEY


def test_sound_http_error_hides_key() -> None:
    with pytest.raises(RuntimeError) as e:
        client(FakeBytes(status=401)).sound("x")
    assert "401" in str(e.value) and FAKE_KEY not in str(e.value)


def test_empty_audio_is_an_error() -> None:
    class Empty(FakeBytes):
        def __call__(self, url: str, body: dict[str, Any], headers: dict[str, str]) -> tuple[int, bytes]:
            return 200, b""

    with pytest.raises(RuntimeError):
        client(Empty()).sound("x")


def test_synthesize_sounds_only_effects_and_cached(prod: Path) -> None:
    b = FakeBytes()
    first = synthesize_sounds(prod, EP, client(b))
    assert [(s.sound, s.status) for s in first] == [("S01", "new"), ("S03", "new")]  # music is never generated
    audio = prod / EP / "audio"
    assert (audio / "S01.mp3").read_bytes() == b"SFX:cup set down on a glass table"
    assert (audio / "S01.key").read_text(encoding="utf-8").strip() == sound_cache_key(SOUNDS[0]["description"])
    assert not (audio / "S02.mp3").exists()
    again = synthesize_sounds(prod, EP, client(b))
    assert [(s.sound, s.status) for s in again] == [("S01", "cached"), ("S03", "cached")]
    assert len(b.calls) == 2


def test_changed_description_recalls_only_that_sound(prod: Path) -> None:
    b = FakeBytes()
    synthesize_sounds(prod, EP, client(b))
    path = prod / EP / "lines.yaml"
    path.write_text(path.read_text(encoding="utf-8").replace("door slam", "door creak"), encoding="utf-8")
    again = synthesize_sounds(prod, EP, client(b))
    assert [(s.sound, s.status) for s in again] == [("S01", "cached"), ("S03", "new")]
    assert len(b.calls) == 3


def test_a_file_without_key_is_provided_and_kept(prod: Path) -> None:
    audio = prod / EP / "audio"
    audio.mkdir(parents=True)
    (audio / "S03.wav").write_bytes(b"MY OWN DOOR")
    b = FakeBytes()
    out = synthesize_sounds(prod, EP, client(b))
    assert [(s.sound, s.status) for s in out] == [("S01", "new"), ("S03", "provided")]
    assert (audio / "S03.wav").read_bytes() == b"MY OWN DOOR" and not (audio / "S03.mp3").exists()
    assert len(b.calls) == 1


def test_sound_cache_key() -> None:
    assert sound_cache_key("a") == sound_cache_key("a") and sound_cache_key("a") != sound_cache_key("b")
    assert len(sound_cache_key("a")) == 64


def test_cli_prints_sounds_after_lines(
    prod: Path, capsys: pytest.CaptureFixture[str], monkeypatch: pytest.MonkeyPatch
) -> None:
    b = FakeBytes()
    import karagoz.voice.elevenlabs as el

    monkeypatch.setattr(el, "ElevenLabs", lambda: client(b))
    assert cli.main(["voice", str(prod), EP]) == 0
    out = capsys.readouterr().out.splitlines()
    assert out == ["L01 new 1.70 s", "L02 new 1.20 s", "S01 new", "S03 new"]


def test_no_sounds_no_calls(tmp_path: Path) -> None:
    p = tmp_path / "prod"
    (p / EP).mkdir(parents=True)
    shutil.copy(FIX / "lines.yaml", p / EP / "lines.yaml")
    b = FakeBytes()
    assert synthesize_sounds(p, EP, client(b)) == [] and b.calls == []
